import { Component, Element, Host, Prop, State, h } from "@stencil/core";
import { check } from "../../../../icons/index";
import getBootstrapConfig from "../../../utils/getBootstrapConfig";

/**
 * @since 0.0.6
 * @status deprecated
 *
 */
@Component({
	tag: "hbr-workflow-step",
	styleUrl: "workflow-step.scss",
	shadow: true,
})
export class HbrWorkflowStep {
	@Element() host: HTMLHbrWorkflowStepElement;

	@Prop() current = false;

	@Prop() completed = false;

	@Prop() disabled = false;

	@Prop() number: number;

	@Prop() stepTitle: string;

	@Prop() stepperActive = true;

	@State() hovered = false;

	private onHover = (value) => {
		this.hovered = value;
	};

	render() {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		console.error(
			"hbr-workflow-step is deprecated in January 2025. Please use hbr-stepper instead.",
		);
		return (
			<Host>
				<div
					class={`
            wf-step
            ${this.hovered ? "wf-step_hovered" : ""}
            ${this.current ? "wf-step_current" : ""}
            ${this.disabled ? "wf-step_disabled" : ""}
            ${this.completed ? "wf-step_completed" : ""}
            ${
							!this.completed && !this.disabled && !this.current
								? "wf-step_idle"
								: ""
						}
            ${
							!this.completed && !this.disabled && !this.current && this.hovered
								? "wf-step_idle_hovered"
								: ""
						}
            ${!this.stepperActive ? "wf-step_not-active" : ""}
          `}
					onMouseEnter={() => this.onHover(true)}
					onMouseLeave={() => this.onHover(false)}
				>
					<div class="wf-step-number">
						{this.completed && !this.current ? (
							<hbr-icon
								asset={customSystemIcons?.check || check}
								class="wf-step-completed-icon"
							/>
						) : (
							this.number
						)}
					</div>
					<div class="wf-step-title">{this.stepTitle}</div>
					<div class="wf-step-border-right" />
				</div>
			</Host>
		);
	}
}
