import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Fragment,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import { remove } from "../../../icons";
import { addConstructedStyle } from "../../utils/browser";
import { focusVisible } from "../../utils/focus-visible";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import { internationalization } from "../../utils/i18n/translations";
import {
	getCssRulesForSentiment,
	getCssRulesForSentimentBanner,
} from "../../utils/sentiments";
import { hasSlot } from "../../utils/slot";
import translations from "./i18n";
const toastStack = Object.assign(document.createElement("div"), {
	className: "hbr-toast-stack",
});
const DEFAULT_BANNER_DURATION = Number.POSITIVE_INFINITY;
const DEFAULT_INFO_POSITIVE_TOAST_DURATION = 6000;
const DEFAULT_WARNING_TOAST_DURATION = 8000;

/**
 * @since 0.0.10
 * @status statable
 *
 * @description "Notifications inform users of a process that an app has performed or will perform. They are of different types: Inline, Banners and Toasts
 *
 * @slot - The banner's content.
 * @slot icon - An icon to show in the banner.
 *
 * @part base - The component's base wrapper.
 * @part icon - The container that wraps the banner icon.
 * @part message - The banner message.
 * @part close-button - The close button.
 * @part multi - multi banner wrapper.
 * @part title - multi banner title.
 * @part messages - multi banner messages.
 *
 * @data-testid banner-close - The close button.
 */

interface Aria {
	label?: string;
	describedby?: string;
	invalid?: boolean;
	role?: string;
	expanded?: boolean;
	clear?: string;
	level?: string | number;
}

interface i18n {
	hideAlerts?: string;
	viewAlerts?: string;
}

@Component({
	tag: "hbr-banner",
	styleUrl: "banner.scss",
	shadow: true,
})
export class Banner {
	banner: HTMLElement;
	btn: HTMLElement;
	autoHideTimeout: number | NodeJS.Timeout;
	autoCollapseTimeout: number | NodeJS.Timeout;
	private multiBanner: boolean;
	private toastDuration?: number;
	sheet: CSSStyleSheet = new CSSStyleSheet();

	private defaultAria: Aria = {
		clear: "Remove this alert message",
	};

	@Element() host: HTMLHbrBannerElement;

	@State() isVisible = false;
	@State() isExpanded = false;
	@State() hasMessagesSlot = false;

	/** Indicates whether or not the banner is open. You can use this in lieu of the show/hide methods. */
	@Prop({ mutable: true, reflect: true }) open = false;

	/** Indicates whether or not the multi banner is expanded. You can use this in lieu of the expand/collapse methods. */
	@Prop({ mutable: true, reflect: true }) expanded = false;

	/** Set to true to make the banner closable. */
	@Prop({ reflect: true }) closable = false;

	/** The sentiment determines the status icon and banner color. */
	@Prop({ reflect: true }) sentiment:
		| "success"
		| "info"
		| "warning"
		| "danger"
		| string;

	/** The variant of banner. */
	@Prop({ reflect: true }) variant: "fill" | "plain" | "outline" = "outline";

	/**
	 * The length of time, in milliseconds, the banner will show before closing itself. If the user interacts with the
	 * banner before it closes (e.g. moves the mouse over it), the timer will restart. Toasts use a 6000 millisecond
	 * duration for success and info toasts, or 8000 milliseconds for warning toasts.
	 */
	@Prop() duration = DEFAULT_BANNER_DURATION;

	/** Whether there are multiple messages displayed in this banner. */
	@Prop({ reflect: true }) multiple = false;

	/** As a child banner inside of the multiple banner. */
	@Prop({ reflect: true }) child = false;

	/** Heading level of the title */
	@Prop() arialevel = "3";

	/** Product level banner */
	@Prop({ reflect: true }) product: boolean;

	/**  language defaults for month and weekday names (see internationalization below) */
	@Prop({ mutable: true }) i18n: i18n;

	/** Attributes related to screen readers. */
	@Prop() aria: Aria;

	@Watch("open")
	handleOpenChange() {
		this.open ? this.show() : this.hide();
	}

	@Watch("expanded")
	handleExpandChange() {
		if (this.expanded) {
			this.expand();
			this.isExpanded = true;
		} else {
			this.collapse();
			this.isExpanded = false;
		}
	}

	@Watch("duration")
	handleDurationChange() {
		if (this.toastDuration !== undefined) {
			this.toastDuration = this.getToastDuration();
		}
		this.restartAutoHide();
	}

	/** Emitted when the banner opens. Calling `event.preventDefault()` will prevent it from being opened. */
	@Event({ eventName: "hbr-show" }) hbrShow: EventEmitter;

	/** Emitted after the banner opens and all transitions are complete. */
	@Event({ eventName: "hbr-after-show" }) hbrAfterShow: EventEmitter;

	/** Emitted when the banner closes. Calling `event.preventDefault()` will prevent it from being closed. */
	@Event({ eventName: "hbr-hide" }) hbrHide: EventEmitter;

	/** Emitted after the banner closes and all transitions are complete. */
	@Event({ eventName: "hbr-after-hide" }) hbrAfterHide: EventEmitter;

	/** Emitted when the multi banner expands. Calling `event.preventDefault()` will prevent it from being expanded. */
	@Event({ eventName: "hbr-expand" }) hbrExpand: EventEmitter;

	/** Emitted after the multi banner expands and all transitions are complete. */
	@Event({ eventName: "hbr-after-expand" }) hbrAfterExpand: EventEmitter;

	/** Emitted when the multi banner collapsed. Calling `event.preventDefault()` will prevent it from being collapsed. */
	@Event({ eventName: "hbr-collapse" }) hbrCollapse: EventEmitter;

	/** Emitted after the multi banner collapsed and all transitions are complete. */
	@Event({ eventName: "hbr-after-collapse" }) hbrAfterCollapse: EventEmitter;

	connectedCallback() {
		this.handleCloseClick = this.handleCloseClick.bind(this);
		this.handleMouseMove = this.handleMouseMove.bind(this);
		this.handleTransitionEnd = this.handleTransitionEnd.bind(this);
		this.handleExpandClick = this.handleExpandClick.bind(this);
		this.handleSlotChange = this.handleSlotChange.bind(this);
		this.sheet = new CSSStyleSheet();
	}

	componentWillLoad() {
		// Show on init if open
		if (this.open) {
			this.show();
		}
		if (this.expanded) {
			this.expand();
		}
		this.handleSlotChange();
		this.multiBanner =
			(this.variant === "fill" || this.variant === "outline") && this.multiple;

		if (this.multiBanner && this.expanded) {
			this.isExpanded = true;
		}
	}

	/** Shows the banner. */
	@Method()
	async show() {
		// Prevent subsequent calls to the method, whether manually or triggered by the `open` watcher
		if (this.isVisible) {
			return;
		}

		const hbrShow = this.hbrShow.emit();
		if (hbrShow.defaultPrevented) {
			this.open = false;
			return;
		}

		this.isVisible = true;
		this.open = true;

		this.restartAutoHide();
	}

	/** Hides the banner */
	@Method()
	async hide() {
		// Prevent subsequent calls to the method, whether manually or triggered by the `open` watcher
		if (!this.isVisible) {
			return;
		}

		const hbrHide = this.hbrHide.emit();
		if (hbrHide.defaultPrevented) {
			this.open = true;
			return;
		}

		clearTimeout(this.autoHideTimeout);
		this.toastDuration = undefined;
		this.isVisible = false;
		this.open = false;
	}

	/** Expands the multi banner. */
	@Method()
	async expand() {
		const hbrExpand = this.hbrExpand.emit();
		if (hbrExpand.defaultPrevented) {
			this.expanded = false;
			return;
		}

		this.expanded = true;
		if (this.duration < Number.POSITIVE_INFINITY) {
			this.autoCollapseTimeout = setTimeout(
				() => this.collapse(),
				this.duration,
			);
		}
	}

	/** Collapse the multi banner */
	@Method()
	async collapse() {
		const hbrCollapse = this.hbrCollapse.emit();
		if (hbrCollapse.defaultPrevented) {
			this.expanded = true;
			return;
		}

		clearTimeout(this.autoCollapseTimeout);
		this.expanded = false;
	}

	/**
	 * Displays the banner as a toast notification. This will move the banner out of its position in the DOM and, when
	 * dismiss, it will be removed from the DOM completely. By storing a reference to the banner, you can reuse it by
	 * calling this method again. The returned promise will resolve after the banner is hidden.
	 */
	@Method()
	async toast() {
		this.toastDuration = this.getToastDuration();
		return new Promise<void>((resolve) => {
			if (!toastStack.parentElement) {
				document.body.append(toastStack);
			}
			this.host.setAttribute("role", "alert");
			this.banner.classList.add("banner--toast");

			toastStack.append(this.host);
			const closeBtn = this.btn?.shadowRoot.querySelector(
				"button.icon-button",
			) as HTMLElement;
			// Wait for the toast stack to render
			requestAnimationFrame(() => {
				this.host.clientWidth; // force a reflow for the initial transition
				this.show();
				if (this.closable && closeBtn) {
					focusVisible.observe(closeBtn);
				}
			});

			this.host.addEventListener(
				"hbr-after-hide",
				() => {
					this.host.remove();
					resolve();

					// Remove the toast stack from the DOM when there are no more banners
					if (!toastStack.querySelector("hbr-banner")) {
						toastStack.remove();
					}
					if (this.closable && closeBtn) {
						focusVisible.unobserve(closeBtn);
					}
				},
				{ once: true },
			);
		});
	}

	handleCloseClick() {
		this.hide();
	}

	handleMouseMove() {
		this.restartAutoHide();
	}

	handleExpandClick() {
		this.expanded ? this.collapse() : this.expand();
	}

	handleTransitionEnd(event: TransitionEvent) {
		const target = event.target as HTMLElement;

		// Ensure we only emit one event when the target element is no longer visible
		if (
			event.propertyName === "opacity" &&
			target.classList.contains("banner")
		) {
			this.isVisible = this.open;
			this.open ? this.hbrAfterShow.emit() : this.hbrAfterHide.emit();
			if (this.child && !this.open) {
				const parent = this.host.closest(
					"hbr-banner:not([child])",
				) as HTMLHbrBannerElement;
				const banners = parent?.querySelectorAll("hbr-banner");
				if (banners?.length === 1) {
					parent.collapse();
					parent.remove();
				}
			}
		}
	}

	restartAutoHide() {
		clearTimeout(this.autoHideTimeout);
		const duration = this.toastDuration ?? this.duration;
		if (this.open && duration < Number.POSITIVE_INFINITY) {
			this.autoHideTimeout = setTimeout(() => this.hide(), duration);
		}
	}

	private getToastDuration() {
		return this.duration === DEFAULT_BANNER_DURATION
			? this.getDefaultToastDuration()
			: this.duration;
	}

	private getDefaultToastDuration() {
		const sentiment = this.sentiment?.toLowerCase() || "";
		if (sentiment === "danger") {
			return DEFAULT_BANNER_DURATION;
		}

		return sentiment === "warning"
			? DEFAULT_WARNING_TOAST_DURATION
			: DEFAULT_INFO_POSITIVE_TOAST_DURATION;
	}

	handleSlotChange() {
		this.hasMessagesSlot = hasSlot(this.host, "messages");
	}

	render() {
		const { sentiment } = this;
		//Demo purpose
		let customLang: string | undefined;
		if (this.multiple) {
			customLang = this.host.parentElement?.lang;
		}

		const cls = {
			banner: true,
			"banner--open": this.open,
			"banner--visible": this.isVisible,
			"banner--closable": this.closable,
			"banner--multi": this.multiple,
			"banner--multiBanner": this.multiBanner,
			"banner--child": this.child,
			"banner--product": this.product,
			"banner--expanded": this.isExpanded,
			"banner--collapsed": !this.isExpanded,
			"banner--outline-collapsible":
				this.variant === "outline" && this.multiBanner,
		};
		cls[`banner--${sentiment ? sentiment : "interact"}`] = true;
		cls[`banner--${this.variant}`] = true;

		let multiPart = "";
		if (this.multiBanner) {
			if (this.variant === "outline") {
				multiPart = "outline-multi";
			} else if (this.variant === "fill") {
				multiPart = "fill-multi";
			}
		}

		const part = `base ${this.variant} ${multiPart}`;

		const banner = () => {
			return (
				<div
					ref={(el) => {
						this.banner = el;
					}}
					part={part}
					class={cls}
					role={"alert"}
					aria-live={sentiment !== "danger" ? "polite" : "assertive"}
					aria-atomic="true"
					aria-hidden={this.open ? "false" : "true"}
					onMouseMove={this.handleMouseMove}
					onTransitionEnd={this.handleTransitionEnd}
				>
					{!this.multiBanner &&
						(this.multiple ? bannerMessages() : bannerMessage())}
					{!this.multiBanner && this.closable && closableIcon()}

					{/** MultiBanner */}
					{this.multiBanner && bannerMessage()}
					{this.multiBanner && this.closable && closableIcon()}
					{this.multiBanner && <slot name="dismiss" />}
				</div>
			);
		};

		const bannerMessage = () => {
			return (
				<Fragment>
					<span part="icon" class="banner__icon">
						<slot name="icon" />
					</span>
					<span part="message" class="banner__message">
						<slot />
					</span>
				</Fragment>
			);
		};

		const bannerMessages = () => {
			const { hideAlerts, viewAlerts } = this.i18n || {};
			const _hideAlerts = hideAlerts
				? hideAlerts
				: internationalization(
						translations,
						"hideAlerts",
						customLang as "en" | "ja" | "ko" | "zn",
				  );
			const _viewAlerts = viewAlerts
				? viewAlerts
				: internationalization(
						translations,
						"viewAlerts",
						customLang as "en" | "ja" | "ko" | "zn",
				  );

			return (
				<Fragment>
					<span class="multi__empty_span" />
					<div part="multi" class="banner__multi">
						<div
							part="title"
							class="banner__title"
							role="heading"
							aria-level={this.aria?.level || this.arialevel}
						>
							<slot name="title" />
						</div>
						<hbr-button
							variant="outline"
							class="banner__expand_button"
							onClick={this.handleExpandClick}
							aria={{
								expanded: this.expanded?.toString(),
							}}
						>
							{this.expanded ? _hideAlerts : _viewAlerts}
						</hbr-button>
						<div
							class={{
								banner__alerts: true,
								banner__expand: this.expanded,
								banner__collapse: !this.expanded,
							}}
						>
							<slot name="banner" />
						</div>
					</div>
				</Fragment>
			);
		};
		const multiBannerMessages = () => {
			const { isExpanded } = this;
			return (
				<div
					part="messages"
					class={`banner__multiBanner ${
						isExpanded ? "message__expand" : "message__collapse"
					}`}
				>
					{this.isExpanded && (
						<slot name="messages" onSlotchange={this.handleSlotChange} />
					)}
				</div>
			);
		};
		const closableIcon = () => {
			const customSystemIcons = getBootstrapConfig()?.systemIcons;
			return (
				<hbr-icon-button
					exportparts="base:close-button"
					asset={customSystemIcons?.remove || remove}
					ref={(el) => {
						this.btn = el;
					}}
					class="banner__close"
					arialabel={this.aria?.clear || this.defaultAria?.clear}
					onClick={this.handleCloseClick}
					data-testid="banner-close"
				/>
			);
		};
		if (this.host) {
			this.sheet.replaceSync(`
				:host {
					${getCssRulesForSentimentBanner({
						sentiment: sentiment || "interact",
						variant: this.variant || "",
						type: "background",
					})}
					${getCssRulesForSentimentBanner({
						sentiment,
						variant: this.variant,
						type: "border",
					})}
				}
				.banner__icon {
					${getCssRulesForSentiment({
						sentiment: sentiment || "interact",
						type: "icon",
					})}
				}
			`);
			addConstructedStyle(this.host.shadowRoot, this.sheet);
		}

		return (
			<Fragment>
				{this.multiBanner ? (
					<div
						part={"multiBanner"}
						class={`multi--collapsible ${this.variant}-collapsible ${
							this.isExpanded ? " multi--collapsible-expanded" : ""
						}`}
					>
						{banner()}
						{multiBannerMessages()}
					</div>
				) : (
					banner()
				)}
			</Fragment>
		);
	}
}
