import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Host,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import { remove } from "../../../icons";
import { isPreventScrollSupported } from "../../utils/browser";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import {
	handleEndSentinelFocus,
	handleStartSentinelFocus,
} from "../../utils/keyboardHelper";
import ModalElement from "../../utils/modal";
import { lockBodyScrolling, unlockBodyScrolling } from "../../utils/scroll";
import { hasSlot } from "../../utils/slot";

const hasPreventScroll = isPreventScrollSupported();

let id = 0;

/**
 * @since 0.0.10
 * @status stable
 *
 * @description The accordion enables showing and hiding sections of related content on a page.
 *
 * @slot - The modal's content.
 * @slot label - The modal's label. Alternatively, you can use the label prop.
 * @slot footer - The modal's footer, usually one or more buttons representing various options.
 *
 * @part base - The component's base wrapper.
 * @part overlay - The overlay.
 * @part panel - The modal panel (where the modal and its content is rendered).
 * @part header - The modal header.
 * @part title - The modal title.
 * @part close-button - The close button.
 * @part body - The modal body.
 * @part footer - The modal footer.
 * @part closer - The modal closer icon.
 *
 * @class hbr-modal-alert-icon - Class to style icon inside Alerts
 * @class hbr-modal-alert-title - Class to style title inside Alerts
 * @class hbr-modal-alert-message - Class to style message inside Alerts
 */
@Component({
	tag: "hbr-modal",
	styleUrl: "modal.scss",
	shadow: true,
})
export class Modal {
	componentId = `modal-${++id}`;
	modal: HTMLElement;
	modalElement: ModalElement;
	panel: HTMLElement;
	willShow = false;
	willHide = false;

	@Element() host: HTMLHbrModalElement;

	@State() hasFooter = false;
	@State() isVisible = false;

	/** Indicates whether or not the modal is open. You can use this in lieu of the show/hide methods. */
	@Prop({ mutable: true, reflect: true }) open = false;

	/** Enable the native popover feature so that the modal layers above clipping containers. @version: 2.18.46 */
	@Prop() enablePopover = false;

	/**
	 * The modal's label as displayed in the header. You should always include a relevant label even when using
	 * `no-header`, as it is required for proper accessibility.
	 */
	@Prop() label = "";

	/**
	 * Set to true to disable the header. This will also remove the default close button, so please ensure you provide an
	 * easy, accessible way for users to dismiss the modal.
	 */
	@Prop() noHeader = false;

	/**
	 * The modal's width. Use the css prop --width for custom sizes.
	 */
	@Prop({ reflect: true }) size: "xsmall" | "small" | "medium" | "large" = null;

	/**
	 * Determines whether header and footer elements' styles adapt to scroll
	 */
	@Prop({ reflect: true }) scrollAware = false;

	/** Attributes related to screen readers. */
	@Prop() aria: { labelledby?: string; role?: string; describedby?: string };

	@Watch("open")
	handleOpenChange() {
		this.open ? this.show() : this.hide();
	}

	/** Emitted when the modal opens. Calling `event.preventDefault()` will prevent it from being opened. */
	@Event({ eventName: "hbr-show" }) hbrShow: EventEmitter;

	/** Emitted after the modal opens and all transitions are complete. */
	@Event({ eventName: "hbr-after-show" }) hbrAfterShow: EventEmitter;

	/** Emitted when the modal closes. Calling `event.preventDefault()` will prevent it from being closed. */
	@Event({ eventName: "hbr-hide" }) hbrHide: EventEmitter;

	/** Emitted after the modal closes and all transitions are complete. */
	@Event({ eventName: "hbr-after-hide" }) hbrAfterHide: EventEmitter;

	/**
	 * Emitted when the modal opens and the panel gains focus. Calling `event.preventDefault()` will prevent focus and
	 * allow you to set it on a different element in the modal, such as an input or button.
	 */
	@Event({ eventName: "hbr-initial-focus" }) hbrInitialFocus: EventEmitter;

	/** Emitted when the overlay is clicked. Calling `event.preventDefault()` will prevent the modal from closing. */
	@Event({ eventName: "hbr-overlay-dismiss" }) hbrOverlayDismiss: EventEmitter;

	connectedCallback() {
		this.handleCloseClick = this.handleCloseClick.bind(this);
		this.handleTransitionEnd = this.handleTransitionEnd.bind(this);
		this.handleKeyDown = this.handleKeyDown.bind(this);
		this.handleOverlayClick = this.handleOverlayClick.bind(this);
		this.handleSlotChange = this.handleSlotChange.bind(this);

		this.host.addEventListener("keydown", this.handleKeyDown, true);

		this.modalElement = new ModalElement(this.host, {
			onFocusOut: () => this.panel?.focus(),
		});
	}

	componentWillLoad() {
		this.handleSlotChange();

		// Show on init if open
		if (this.open) {
			this.show();
		}
	}

	componentDidLoad() {
		if (this.open && this.enablePopover) {
			this.modal.showPopover();
		}
	}

	disconnectedCallback() {
		this.host.removeEventListener("keydown", this.handleKeyDown, true);
		unlockBodyScrolling(this.host);
	}

	/** Shows the modal */
	@Method()
	async show() {
		if (this.willShow) {
			return;
		}

		const hbrShow = this.hbrShow.emit();
		if (hbrShow.defaultPrevented) {
			this.open = false;
			return;
		}

		this.willShow = true;
		this.isVisible = true;
		this.open = true;
		this.modalElement.activate();

		if (this.enablePopover && this.modal) {
			this.modal.showPopover();
		}

		lockBodyScrolling(this.host);

		if (this.open) {
			if (hasPreventScroll) {
				// Wait for the next frame before setting initial focus so the modal is technically visible
				requestAnimationFrame(() => {
					const hbrInitialFocus = this.hbrInitialFocus.emit();
					if (!hbrInitialFocus.defaultPrevented) {
						this.panel?.focus({ preventScroll: true });
					}
				});
			} else {
				// Once Safari supports { preventScroll: true } we can remove this nasty little hack, but until then we need to
				// wait for the transition to complete before setting focus, otherwise the panel may render in a buggy way its
				// out of view initially.
				//
				// Fiddle: https://jsfiddle.net/g6buoafq/1/
				// Safari: https://bugs.webkit.org/show_bug.cgi?id=178583
				//
				this.modal.addEventListener(
					"transitionend",
					() => {
						const hbrInitialFocus = this.hbrInitialFocus.emit();
						if (!hbrInitialFocus.defaultPrevented) {
							this.panel?.focus();
						}
					},
					{ once: true },
				);
			}
		}
	}

	/** Hides the modal */
	@Method()
	async hide() {
		if (this.willHide) {
			return;
		}

		const hbrHide = this.hbrHide.emit();
		if (hbrHide.defaultPrevented) {
			this.open = true;
			return;
		}

		this.willHide = true;
		this.open = false;
		this.modalElement.deactivate();

		unlockBodyScrolling(this.host);
	}

	handleCloseClick() {
		this.hide();
	}

	handleKeyDown(event: KeyboardEvent) {
		if (event.key === "Escape") {
			this.hide();
		}
	}

	handleOverlayClick() {
		const hbrOverlayDismiss = this.hbrOverlayDismiss.emit();

		if (!hbrOverlayDismiss.defaultPrevented) {
			this.hide();
		}
	}

	handleSlotChange() {
		this.hasFooter = hasSlot(this.host, "footer");
	}

	handleTransitionEnd(event: TransitionEvent) {
		const target = event.target as HTMLElement;

		// Ensure we only emit one event when the target element is no longer visible
		if (
			event.propertyName === "opacity" &&
			target.classList.contains("modal__panel")
		) {
			this.isVisible = this.open;
			this.willShow = false;
			this.willHide = false;
			if (!this.open && this.enablePopover && this.modal) {
				this.modal.hidePopover();
			}
			this.open ? this.hbrAfterShow.emit() : this.hbrAfterHide.emit();
		}
	}

	render() {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		const { role } = this.aria || {};
		const a11y = {
			role: role || "dialog",
			"aria-modal": "true",
			"aria-hidden": this.open ? "false" : "true",
			...(role && role === "alertdialog"
				? { "aria-describedby": `${this.componentId}-content` }
				: {}),
		};
		return (
			<Host
				{...(this.aria?.labelledby
					? {
							role: this.aria.role || "dialog",
							"aria-modal": "true",
							"aria-hidden": this.open ? "false" : "true",
							"aria-labelledby": this.aria.labelledby,
							"aria-describedby": this.aria.describedby,
					  }
					: {})}
			>
				<div
					ref={(el) => {
						this.modal = el;
						if (this.enablePopover && this.modal) {
							this.modal.popover = "manual";
						}
					}}
					part="base"
					class={{
						modal: true,
						"modal--open": this.open,
						"modal--visible": this.isVisible,
						"modal--has-footer": this.hasFooter,
					}}
					onTransitionEnd={this.handleTransitionEnd}
				>
					<div
						part="overlay"
						class="modal__overlay"
						onClick={this.handleOverlayClick}
						tabIndex={-1}
					/>

					<span
						class="modal__focus-sentinel"
						tabIndex={this.open ? 0 : -1}
						onFocus={() => handleStartSentinelFocus(this.panel, "modal")}
						aria-hidden={this.open ? undefined : "true"}
					/>

					<div
						ref={(el) => {
							this.panel = el;
						}}
						part="panel"
						tabIndex={-1}
						class={{
							modal__panel: true,
							//Sizes
							"modal--xsmall": this.size === "xsmall",
							"modal--small": this.size === "small",
							"modal--medium": this.size === "medium",
							"modal--large": this.size === "large",
						}}
						{...(!this.noHeader
							? this.label
								? { ...a11y, "aria-label": this.label }
								: { ...a11y, "aria-labelledby": `${this.componentId}-title` }
							: {})}
					>
						{!this.noHeader && (
							<header part="header" class="modal__header">
								<span
									part="title"
									class="modal__title"
									id={`${this.componentId}-title`}
								>
									<slot name="label">
										{/* If there's no label, use an invisible character to prevent the heading from collapsing */}
										{this.label || String.fromCharCode(65279)}
									</slot>
								</span>
								<hbr-icon-button
									class="modal__close"
									part="closer"
									asset={customSystemIcons?.remove || remove}
									arialabel="Close Modal"
									onClick={this.handleCloseClick}
								/>
							</header>
						)}

						<div
							part="body"
							class="modal__body"
							id={`${this.componentId}-content`}
						>
							<slot />
						</div>

						<footer part="footer" class="modal__footer">
							<slot name="footer" onSlotchange={this.handleSlotChange} />
						</footer>
					</div>

					<span
						class="modal__focus-sentinel"
						tabIndex={this.open ? 0 : -1}
						onFocus={() => handleEndSentinelFocus(this.panel, "modal")}
						aria-hidden={this.open ? undefined : "true"}
					/>

					{this.scrollAware ? <hbr-scroll-view anchor=".modal__body" /> : null}
				</div>
			</Host>
		);
	}
}
